import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    b = list(map(int, data[1:]))

    def can_restore(n, b):
        for a1 in range(1, 10**18 + 1):
            a = [a1]
            valid = True
            for i in range(1, n):
                if b[i-1] != a[-1] % a[0]:
                    valid = False
                    break
                a.append((b[i-1] + a[-1]) // a[0])
            if valid and b[-1] == a[-1] % a[0]:
                return "YES", a
        return "NO", []

    result, a = can_restore(n, b)
    print(result)
    if result == "YES":
        print(" ".join(map(str, a)))

if __name__ == "__main__":
    main()
